import { MakeLogicType, actions, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { InsightsFunctionIconResponse } from '~/types'

export interface InsightsFunctionIconLogicProps {
    logicKey: string
    src?: string
    onChange?: (src: string) => void
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsFunctionIconLogicValues {
    possibleIcons: InsightsFunctionIconResponse[] | null
    possibleIconsLoading: boolean
    searchTerm: string | null
    showPopover: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsFunctionIconLogicActions {
    loadPossibleIcons: () => {
        value: true
    }
    loadPossibleIconsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPossibleIconsSuccess: (
        possibleIcons: {
            id: string
            name: string
            url: string
        }[],
        payload?: {
            value: true
        }
    ) => {
        possibleIcons: {
            id: string
            name: string
            url: string
        }[]
        payload?: {
            value: true
        }
    }
    setSearchTerm: (search: string) => {
        search: string
    }
    setShowPopover: (show: boolean) => {
        show: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsFunctionIconLogicMeta {
    key: string
}

export type insightsFunctionIconLogicType = MakeLogicType<
    insightsFunctionIconLogicValues,
    insightsFunctionIconLogicActions,
    InsightsFunctionIconLogicProps,
    insightsFunctionIconLogicMeta
>

export const insightsFunctionIconLogic = kea<insightsFunctionIconLogicType>([
    props({} as InsightsFunctionIconLogicProps),
    key((props) => props.logicKey ?? 'default'),
    path((key) => ['scenes', 'pipeline', 'hogfunctions', 'insightsFunctionIconLogic', key]),

    actions({
        loadPossibleIcons: true,
        setShowPopover: (show: boolean) => ({ show }),
        setSearchTerm: (search: string) => ({ search }),
    }),

    reducers({
        showPopover: [
            false,
            {
                setShowPopover: (_, { show }) => show,
            },
        ],

        searchTerm: [
            null as string | null,
            {
                setSearchTerm: (_, { search }) => search,
                setShowPopover: () => null,
            },
        ],
    }),

    loaders(({ values }) => ({
        possibleIcons: [
            null as InsightsFunctionIconResponse[] | null,
            {
                loadPossibleIcons: async (_, breakpoint) => {
                    const search = values.searchTerm

                    if (!search) {
                        return []
                    }

                    await breakpoint(1000)
                    const res = await api.insightsFunctions.listIcons({ query: search })
                    return res.map((icon) => ({
                        ...icon,
                        url: icon.url + '&temp=true',
                    }))
                },
            },
        ],
    })),

    listeners(({ actions }) => ({
        setShowPopover: ({ show }) => {
            if (show) {
                actions.loadPossibleIcons()
            }
        },

        setSearchTerm: () => {
            actions.loadPossibleIcons()
        },
    })),
])
